def img(id,alt,cls='',eager=False):
 return f'<img data-fallback="/assets/maternidade-ilustrativa.png" class="{cls}" src="https://images.unsplash.com/{id}?auto=format&amp;fit=crop&amp;w=1000&amp;q=80" alt="{e(alt)}" width="1000" height="800" loading="{"eager" if eager else "lazy"}" decoding="async">'
def card(p):
 c=CATEGORIES[p['category']]
 return f'<article class="post-card"><a class="image-link" href="/blog/{p["slug"]}/">{img(IMAGES[p["image"]],p["title"]) }<span class="image-arrow">↗</span></a><div class="eyebrow">{c[1]} <span>· {p["minutes"]} min de leitura</span></div><h3><a href="/blog/{p["slug"]}/">{p["title"]}</a></h3><p>{p["excerpt"]}</p></article>'
def newsletter():
 return '''<section class="newsletter" id="newsletter"><div><span class="eyebrow">UMA CARTA, DE VEZ EM QUANDO</span><h2>Entre uma descoberta e outra,<br>a gente cresce junto.</h2><p>Reflexões, ideias para a rotina, brincadeiras e descobertas de uma maternidade vivida de verdade. Direto no seu e-mail.</p></div><form data-form="newsletter"><label for="nome-news">Seu nome</label><input id="nome-news" name="name" autocomplete="given-name" placeholder="Como podemos chamar você?" required maxlength="100"><label for="email-news">Seu e-mail</label><input id="email-news" type="email" name="email" autocomplete="email" placeholder="voce@exemplo.com" required maxlength="254"><label class="consent"><input type="checkbox" required> <span>Li a <a href="/privacidade/">Política de Privacidade</a> e concordo em receber a newsletter.</span></label><button class="button" type="submit">Quero fazer parte <span>↗</span></button><p class="form-note">Demonstração: o serviço de e-mail ainda não está conectado.</p><p role="status" class="form-status"></p></form></section>'''
def products(limit=4):
 entries=json.loads((ROOT/'data/affiliate-products.json').read_text())['products']
 cards=[]
 for item in entries[:limit]:
  url=item['affiliate_url']
  if urlsplit(url).scheme!='https' or urlsplit(url).hostname!='meli.la':raise ValueError('Link afiliado inválido')
  name=item.get('name') or f"Seleção {item['id']:02d}"
  cards.append(f'<article class="product-card"><div class="selection-art" aria-hidden="true"><span>entre nós</span><strong>{item["id"]:02d}</strong></div><span class="eyebrow">SELEÇÃO DA CRIADORA · LINK COMISSIONADO</span><h3>{e(name)}</h3><p>Consulte o produto, suas características e a disponibilidade diretamente no anúncio.</p><p class="benefits">Confira vendedor, preço, medidas e condições antes de comprar.</p><a class="offer" href="{e(url)}" target="_blank" rel="sponsored noopener noreferrer" aria-label="Consultar {e(name)} no Mercado Livre, abre em nova aba">Consultar no Mercado Livre <span>↗</span></a></article>')
 return '<div class="products-grid">'+''.join(cards)+'</div>'

NAV=[('/blog/','Conteúdos'),('/categorias/','Por assunto'),('/achadinhos/','Achadinhos'),('/sobre/','Sobre'),('/contato/','Contato')]
def page(path,title,desc,body,article=None):
 url=BASE+path
 canonical=f'<link rel="canonical" href="{e(url)}"><meta property="og:url" content="{e(url)}">' if BASE else ''
 schema={'@context':'https://schema.org','@type':'BlogPosting' if article else 'WebSite','name':title,'inLanguage':'pt-BR'}
 if BASE:schema['url']=url
 if article:schema.update(headline=article['title'],description=desc,image=f'https://images.unsplash.com/{IMAGES[article["image"]]}?auto=format&fit=crop&w=1000&q=80',isAccessibleForFree=True)
 html=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | Entre Nós</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#122C4F">{canonical}<meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{e(title)} | Entre Nós"><meta property="og:description" content="{e(desc)}"><meta property="og:locale" content="pt_BR"><meta property="og:image" content="https://images.unsplash.com/{IMAGES[1]}?auto=format&amp;fit=crop&amp;w=1200&amp;q=80"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')}</script><script src="/assets/app.js" defer></script></head><body><a class="skip" href="#conteudo">Pular para o conteúdo</a><div class="topline">MATERNIDADE, VIDA E TUDO O QUE EXISTE ENTRE ELAS.</div><header class="header"><a class="brand" href="/" aria-label="Entre Nós, início">entre nós<span>MATERNIDADE & VIDA REAL</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span>☰</span></button><nav id="navigation" aria-label="Principal">{''.join(f'<a href="{href}" '+('aria-current="page"' if path==href else '')+f'>{label}</a>' for href,label in NAV)}</nav><a class="search-link" href="/busca/" aria-label="Buscar no portal"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg></a><a class="header-letter" href="#newsletter">Vamos conversar ↗</a></header><main id="conteudo">{body}{newsletter() if path!='/' else ''}</main><footer><div class="footer-top"><a class="brand" href="/">entre nós<span>MATERNIDADE & VIDA REAL</span></a><p>A maternidade faz parte de quem somos.<br>Mas a nossa história vai além.</p><div><span class="eyebrow">FIQUE POR PERTO</span><p>Redes sociais em breve</p><a href="/contato/">Fale com a gente ↗</a></div></div><div class="footer-bottom"><span>© 2026 Entre Nós · Um espaço para a vida como ela é.</span><div><a href="/privacidade/">Privacidade</a><a href="/termos/">Termos de uso</a><a href="/transparencia/">Transparência</a></div></div><p class="disclaimer">Projeto demonstrativo. Imagens ilustrativas, incluindo fotografia gerada por IA, não representam a criadora ou sua família. Conteúdos não substituem orientação profissional.</p></footer></body></html>'''
 html=html.replace('↗', '<svg class="arrow-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>')
 if PREFIX:
  html=html.replace('href="/', 'href="'+PREFIX+'/').replace('src="/', 'src="'+PREFIX+'/').replace('data-fallback="/', 'data-fallback="'+PREFIX+'/')
 target=OUT/(path.strip('/')+'/index.html' if path!='/' else 'index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)
def intro(kicker,title,desc):return f'<section class="page-intro"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{desc}</p></section>'
home=f'''<section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="little-line"></span> A VIDA NÃO VEM COM MANUAL</span><h1>Mãe.<br>Mulher.<br><em>Inteira.</em></h1><p>Entre o colo e o mundo, existe você.<br>Um espaço de conversas sinceras, descobertas e vida real — com tudo o que ela tem.</p><a class="button" href="/blog/">Encontre uma boa leitura <span>↗</span></a><div class="hero-foot"><span>SEM FÓRMULAS. SEM PERFEIÇÃO.</span><span>Só a vida acontecendo.</span></div></div><div class="hero-image"><img src="/assets/maternidade-ilustrativa.png" alt="Imagem gerada e ilustrativa de uma mulher e uma criança brincando juntas; não representa a criadora" width="1024" height="1280" fetchpriority="high"><div class="photo-caption">O EXTRAORDINÁRIO MORA NO COTIDIANO.</div><span class="hero-stamp">vida real<br>por aqui ↗</span></div></section><div class="manifesto-strip"><span>Mais presença.</span><i>✳</i><span>Menos perfeição.</span><i>✳</i><span>Mais você.</span></div><section class="section"><div class="section-heading"><div><span class="eyebrow">UM RESPIRO NO SEU DIA</span><h2>Conversas que acolhem.</h2></div><a class="text-link" href="/blog/">Todos os conteúdos ↗</a></div><div class="posts-grid">{''.join(card(POSTS[i]) for i in [0,1,3])}</div></section><section class="about-strip"><div class="about-mark">nós<span>um encontro<br>de muitas versões.</span></div><div><span class="eyebrow">PRAZER, ENTRE NÓS</span><h2>A mãe é parte da história.<br>A mulher é a história inteira.</h2><p>Um portal pensado a partir do olhar de uma mulher brasileira, mãe de um menino de 3 anos. Para falar de rotina, afetos, descobertas e de tudo o que continua existindo para além da maternidade.</p><p class="small">Apresentação demonstrativa. Nome, biografia e fotografia da criadora serão incluídos por ela.</p><a class="text-link" href="/sobre/">Conheça esse espaço ↗</a></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">CADA FASE, UMA CONVERSA</span><h2>O que faz parte da sua vida?</h2></div></div><div class="category-grid">{''.join(f'<a class="category-tile" href="/categorias/{slug}/"><span class="category-number">{num}</span><h3>{name}</h3><p>{desc}</p><span class="tile-arrow">↗</span></a>' for slug,name,desc,num in CATEGORIES)}</div></section><section class="curation section"><div class="section-heading"><div><span class="eyebrow">MENOS EXCESSO, MAIS SENTIDO</span><h2>Escolhas para a vida real.</h2><p>Links compartilhados pela criadora para você consultar no Mercado Livre.</p></div><a class="text-link" href="/achadinhos/">Ver a curadoria ↗</a></div>{products()}<p class="affiliate-note">Transparência: estes links são de afiliada. Podemos receber comissão por compras elegíveis. Os detalhes dos anúncios e a adequação dos produtos não foram verificados por este portal. <a href="/transparencia/">Entenda a curadoria.</a></p></section><section class="section popular"><div><span class="eyebrow">VALE A LEITURA</span><h2>Para salvar.<br>E voltar depois.</h2><p>Leituras em destaque para acompanhar o seu ritmo.</p><span class="small">Seleção editorial demonstrativa, sem ranking de audiência.</span></div><div>{''.join(f'<a class="popular-row" href="/blog/{p["slug"]}/"><span>0{i+1}</span><div><span class="eyebrow">{CATEGORIES[p["category"]][1]}</span><h3>{p["title"]}</h3></div><b>↗</b></a>' for i,p in enumerate([POSTS[2],POSTS[3],POSTS[5]]))}</div></section>{newsletter()}'''
page('/','Maternidade e vida real','Conversas honestas sobre maternidade, rotina familiar, brincadeiras e a mulher que existe além de ser mãe.',home)
page('/blog/','Conteúdos para a vida real','Explore artigos sobre maternidade real, rotina, autocuidado e desenvolvimento infantil.',intro('NOSSO CADERNO ABERTO','Boas conversas.<br>Novas perspectivas.','Leituras para acompanhar os dias possíveis. Todos os artigos desta versão são demonstrativos.')+'<section class="section no-top"><a class="text-link" href="/busca/">Buscar um assunto ↗</a><div class="posts-grid">'+''.join(card(p) for p in POSTS)+'</div></section>')
page('/categorias/','Todos os assuntos','Encontre leituras pelas sete categorias do portal Entre Nós.',intro('EXPLORE NO SEU RITMO','A vida tem muitos assuntos.','Escolha por onde começar.')+'<section class="section no-top"><div class="category-grid">'+''.join(f'<a class="category-tile" href="/categorias/{s}/"><span class="eyebrow">{n}</span><h2>{t}</h2><p>{d}</p><span>↗</span></a>' for s,t,d,n in CATEGORIES)+'</div></section>')
