for p in POSTS:
 c=CATEGORIES[p['category']]
 body=f'<article class="article"><nav class="breadcrumbs" aria-label="Localização"><a href="/">Início</a> / <a href="/blog/">Blog</a> / <a href="/categorias/{c[0]}/">{c[1]}</a></nav><header class="article-header"><span class="eyebrow">{c[1]}</span><h1>{p["title"]}</h1><p>{p["excerpt"]}</p><div class="article-meta">Redação Entre Nós · Conteúdo demonstrativo · {p["minutes"]} min de leitura</div></header>{img(IMAGES[p["image"]],p["title"],"article-image",True)}<div class="article-body"><p class="notice">Conteúdo demonstrativo, preparado para apresentar a linha editorial. Não relata experiências pessoais da criadora.</p>'+''.join(f'<section><h2>{h}</h2><p>{t}</p></section>' for h,t in p['sections'])+f'<div class="tags">'+''.join(f'<a href="/busca/?q={e(tag)}">#{tag}</a>' for tag in p['tags'])+'</div><button class="button" type="button" data-share>Compartilhar leitura ↗</button><p role="status" id="share-status"></p><a class="text-link" href="/transparencia/">Nossa política editorial ↗</a></div></article><section class="section"><div class="section-heading"><h2>A conversa continua.</h2></div><div class="posts-grid">'+''+'</div></section>'
